def initialize_tracking_and_permissions(apps, schema_editor):
    alias = schema_editor.connection.alias
    Permission = apps.get_model('boldApp_core', 'Permission')
    for action, description, risk in [
        ('manage', 'Configurar las etapas de una tarea.', 'medium'),
        ('advance', 'Iniciar, bloquear, completar o revisar mis etapas.', 'medium'),
        ('override', 'Omitir o retirar una etapa mediante una excepción motivada.', 'high'),
    ]:
        Permission.objects.using(alias).get_or_create(code='tasks.execution.'+action, defaults={
            'module_code':'tasks','resource':'execution','action':action,'description':description,
            'risk_level':risk,'is_active':True,'is_delegable':True,'is_bulk_assignable':action!='override'})
    Task = apps.get_model('boldApp_tareas', 'Task')
    Tracking = apps.get_model('boldApp_tareas', 'TaskTracking')
    # A baseline documents observation coverage; it never invents transitions.
    now = timezone.now()
    pending = []
    for key in Task.objects.using(alias).values_list('pk', flat=True).iterator(chunk_size=1000):
        pending.append(Tracking(task_id=key, observed_since=now, complete_history=False))
        if len(pending) == 1000:
            Tracking.objects.using(alias).bulk_create(pending, ignore_conflicts=True); pending=[]
    if pending:
        Tracking.objects.using(alias).bulk_create(pending, ignore_conflicts=True)


